definition.script:
pipeline {
  agent any

  tools {
    nodejs 'node25'
  }

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 30, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/nexus-command.git'
      }
    }
    stage('Install') {
      steps { sh 'npm ci --no-audit --no-fund' }
    }
    stage('Lint') {
      steps { sh 'npm run lint --if-present || echo "WARN: lint non-blocking"' }
    }
    stage('Unit tests') {
      steps { sh 'npm run test:unit --if-present || echo "WARN: unit tests non-blocking"' }
    }
    stage('Build') {
      steps { sh 'NODE_OPTIONS=--max-old-space-size=2048 npm run build' }
    }
  }

  post {
    always { cleanWs() }
  }
}
